import React from 'react';
import { View, Modal, Pressable } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { cn } from '../lib/utils';

interface BottomSheetProps {
  visible: boolean;
  onClose: () => void;
  children: React.ReactNode;
  height?: number | string;
  className?: string;
}

export function BottomSheet({
  visible,
  onClose,
  children,
  height,
  className,
}: BottomSheetProps) {
  return (
    <Modal
      visible={visible}
      transparent
      animationType="slide"
      onRequestClose={onClose}
    >
      <View className="flex-1" style={{ backgroundColor: 'rgba(0,0,0,0.6)' }}>
        <Pressable className="flex-1" onPress={onClose} />
        <View
          className={cn('bg-bgElevated rounded-t-2xl', className)}
          style={typeof height === 'number' ? { height } : undefined}
        >
          <View className="items-center pt-2 pb-2">
            <View className="w-9 h-1 rounded-full bg-borderStrong" />
          </View>
          {children}
          <SafeAreaView edges={['bottom']} />
        </View>
      </View>
    </Modal>
  );
}

import React from 'react';
import { View, Text } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Button } from './button';
import { cn } from '../lib/utils';

interface EmptyStateProps {
  icon?: keyof typeof Ionicons.glyphMap;
  title: string;
  description?: string;
  actionLabel?: string;
  onAction?: () => void;
  className?: string;
}

export function EmptyState({
  icon = 'cube-outline',
  title,
  description,
  actionLabel,
  onAction,
  className,
}: EmptyStateProps) {
  return (
    <View className={cn('items-center justify-center py-16 px-8', className)}>
      <View className="w-16 h-16 rounded-full bg-bgHover items-center justify-center mb-4">
        <Ionicons name={icon} size={28} color="#666666" />
      </View>
      <Text className="text-[17px] font-semibold text-textPrimary text-center">
        {title}
      </Text>
      {description ? (
        <Text className="text-[14px] text-textSecondary text-center mt-2 leading-5">
          {description}
        </Text>
      ) : null}
      {actionLabel && onAction ? (
        <Button
