import { useEffect, useRef, useState } from 'react';
import { AppState, type AppStateStatus } from 'react-native';
import {
  dgateway,
  isTerminalStatus,
  type PaymentStatus,
  type PaymentStatusResponse,
} from '../lib/dgateway';

interface UsePaymentStatusOptions {
  /** Transaction reference returned by `dgateway.startPayment`. */
  reference: string | null | undefined;
  /** Poll interval in ms (default 5000 — matches DGateway recommendations). */
  intervalMs?: number;
  /** Hard ceiling in ms before stopping (default 5 minutes). */
  ceilingMs?: number;
  /** Pause polling when the app is backgrounded (default true). */
  pauseWhenBackground?: boolean;
  /** Called once when status transitions to a terminal state. */
  onTerminal?: (status: PaymentStatusResponse) => void;
}

interface UsePaymentStatusResult {
  status: PaymentStatus;
  data: PaymentStatusResponse | null;
  error: Error | null;
  /** True while polling is active and status is not terminal. */
  isPolling: boolean;
  /** True when the 5-minute ceiling has been reached. */
  timedOut: boolean;
  /** Stop polling early (e.g., user cancelled). */
  cancel: () => void;
  /** Manually force a status check. */
  refetch: () => Promise<void>;
}

/**
 * Foreground 5-second poll of /api/checkout/status/:ref with a 5-minute ceiling.
 * Cancels on unmount, pauses on background. Designed for mobile money STK push UX.
 */
export function usePaymentStatus({
  reference,
  intervalMs = 5_000,
  ceilingMs = 5 * 60_000,
  pauseWhenBackground = true,
  onTerminal,
}: UsePaymentStatusOptions): UsePaymentStatusResult {
  const [data, setData] = useState<PaymentStatusResponse | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [status, setStatus] = useState<PaymentStatus>('pending');
  const [isPolling, setIsPolling] = useState(false);
  const [timedOut, setTimedOut] = useState(false);

  const startedAtRef = useRef<number | null>(null);
  const cancelledRef = useRef(false);
  const intervalRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const appStateRef = useRef<AppStateStatus>('active');
  const onTerminalRef = useRef(onTerminal);

  useEffect(() => {
    onTerminalRef.current = onTerminal;
  }, [onTerminal]);

  const stop = () => {
    if (intervalRef.current) {
      clearTimeout(intervalRef.current);
      intervalRef.current = null;
    }
    setIsPolling(false);
  };

  const cancel = () => {
    cancelledRef.current = true;
    stop();
  };

  const tick = async () => {
    if (!reference || cancelledRef.current) return;

    if (pauseWhenBackground && appStateRef.current !== 'active') {
      intervalRef.current = setTimeout(tick, intervalMs);
      return;
    }

    if (startedAtRef.current !== null && Date.now() - startedAtRef.current >= ceilingMs) {
      setTimedOut(true);
      stop();
      return;
    }

    try {
      const res = await dgateway.getStatus(reference);
      if (cancelledRef.current) return;

      setData(res);
      setStatus(res.status);

      if (isTerminalStatus(res.status)) {
        stop();
        onTerminalRef.current?.(res);
        return;
      }
    } catch (err) {
      // Don't terminate on transient network errors — keep polling.
      setError(err as Error);
    }

    if (!cancelledRef.current) {
      intervalRef.current = setTimeout(tick, intervalMs);
    }
  };

  const refetch = async () => {
    await tick();
  };

  useEffect(() => {
    if (!reference) return;

    cancelledRef.current = false;
    startedAtRef.current = Date.now();
    setIsPolling(true);
    setTimedOut(false);
    setError(null);

    const sub = AppState.addEventListener('change', (next) => {
      appStateRef.current = next;
    });

    tick();

    return () => {
      cancelledRef.current = true;
      stop();
      sub.remove();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reference, intervalMs, ceilingMs, pauseWhenBackground]);

  return { status, data, error, isPolling, timedOut, cancel, refetch };
}

import React from 'react';
import { View, Text, ScrollView, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useForm, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Input } from '../ui/input';
import { Button } from '../ui/button';
import { ScreenHeader } from '../shared/screen-header';
import { dgateway, type Currency } from '../lib/dgateway';

interface MobileMoneyPayScreenProps {
  /** Amount in whole units of currency — pass via route param or prop. */
  defaultAmount?: number;
  /** Pre-filled buyer phone (e.g., from logged-in user profile). */
  defaultPhone?: string;
  defaultCurrency?: Currency;
  /** Free-form description shown on the buyer's bank/wallet statement. */
  description: string;
  /** Metadata attached to the transaction (e.g., orderId). */
  metadata?: Record<string, string | number | boolean>;
  /** Called with the DGateway reference once the prompt is sent. Navigate to a status screen here. */
  onStarted: (reference: string) => void;
  /** Page title. */
  title?: string;
}

const phoneRegex = /^(\+?256|0)?7\d{8}$|^(\+?254|0)?[71]\d{8}$|^(\+?255|0)?[67]\d{8}$|^(\+?250|0)?7\d{8}$/;

const schema = z.object({
  amount: z
    .string()
    .min(1, 'Required')
    .refine((s) => /^\d+$/.test(s) && Number(s) > 0, 'Whole numbers only'),
  phone: z
    .string()
    .min(9, 'Enter a valid phone')
    .refine((s) => phoneRegex.test(s.trim()), 'Use 07X… or 2567X…'),
});

type FormValues = z.infer<typeof schema>;

const CURRENCIES: { code: Currency; label: string }[] = [
  { code: 'UGX', label: '🇺🇬 UGX' },
  { code: 'KES', label: '🇰🇪 KES' },
  { code: 'TZS', label: '🇹🇿 TZS' },
  { code: 'RWF', label: '🇷🇼 RWF' },
];

export function MobileMoneyPayScreen({
  defaultAmount,
  defaultPhone,
  defaultCurrency = 'UGX',
  description,
  metadata,
  onStarted,
  title = 'Pay with mobile money',
}: MobileMoneyPayScreenProps) {
  const [currency, setCurrency] = React.useState<Currency>(defaultCurrency);
  const [submitting, setSubmitting] = React.useState(false);

  const { control, handleSubmit, formState: { errors } } = useForm<FormValues>({
    resolver: zodResolver(schema),
    defaultValues: {
      amount: defaultAmount ? String(defaultAmount) : '',
      phone: defaultPhone ?? '',
    },
  });

  async function onSubmit(values: FormValues) {
    setSubmitting(true);
    try {
      const res = await dgateway.startPayment({
        amount: Number(values.amount),
        currency,
        phoneNumber: values.phone.trim(),
        description,
        metadata,
      });
      onStarted(res.reference);
    } catch (err) {
      Alert.alert(
        'Payment could not start',
        (err as Error).message || 'Please try again in a moment.',
      );
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <SafeAreaView edges={['top']} className="flex-1 bg-bg">
      <ScreenHeader title={title} />
      <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={{ padding: 16 }}>
        <View className="rounded-2xl bg-bgElevated border border-border p-5">
          <Text className="text-textSecondary text-[13px]">You&apos;ll be charged</Text>

          {/* Currency switcher */}
          <View className="mt-3 flex-row gap-2 flex-wrap">
            {CURRENCIES.map((c) => {
              const active = c.code === currency;
              return (
                <Text
                  key={c.code}
                  onPress={() => setCurrency(c.code)}
                  className={[
                    'px-3 py-1.5 rounded-full text-[12px] font-medium',
                    active
                      ? 'bg-accent text-white'
                      : 'bg-bgSubtle text-textSecondary border border-border',
                  ].join(' ')}
                >
                  {c.label}
                </Text>
              );
            })}
          </View>

          {/* Amount input */}
          <View className="mt-4">
            <Controller
              control={control}
              name="amount"
              render={({ field: { value, onChange } }) => (
                <Input
                  label="Amount"
                  value={value}
                  onChangeText={onChange}
                  placeholder="0"
                  keyboardType="number-pad"
                  error={errors.amount?.message}
                  variant="currency"
                  currencySymbol={currency}
                />
              )}
            />
          </View>

          {/* Phone input */}
          <View className="mt-4">
            <Controller
              control={control}
              name="phone"
              render={({ field: { value, onChange } }) => (
                <Input
                  label="Mobile money number"
                  value={value}
                  onChangeText={onChange}
                  placeholder="0771234567"
                  keyboardType="phone-pad"
                  leftIcon="call-outline"
                  error={errors.phone?.message}
                  helperText="We&apos;ll send a confirmation prompt to this number."
                />
              )}
            />
          </View>
        </View>

        <Text className="mt-5 text-textTertiary text-[12.5px] leading-relaxed">
          DGateway routes mobile-money payments automatically. UGX goes through Iotec; KES, TZS, and RWF
          through Relworx. The buyer approves the STK push on their phone — usually within 90 seconds.
        </Text>

        <View className="mt-6">
          <Button
            title="Send payment prompt"
            onPress={handleSubmit(onSubmit)}
            loading={submitting}
            icon="phone-portrait-outline"
            variant="primary"
            size="lg"
          />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

import React from 'react';
import { View, Text, ActivityIndicator } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { Button } from '../ui/button';
import { ScreenHeader } from '../shared/screen-header';
import { colors } from '../lib/theme';
import { usePaymentStatus } from './use-payment-status';
import {
  type PaymentStatusResponse,
  isTerminalStatus,
  statusLabel,
} from '../lib/dgateway';

interface PaymentStatusScreenProps {
  reference: string;
  onSuccess: (status: PaymentStatusResponse) => void;
  onFailure: (status: PaymentStatusResponse | null, reason: 'failed' | 'cancelled' | 'expired' | 'timeout') => void;
  onCancel?: () => void;
  title?: string;
}

export function PaymentStatusScreen({
  reference,
  onSuccess,
  onFailure,
  onCancel,
  title = 'Confirm payment',
}: PaymentStatusScreenProps) {
  const { status, data, isPolling, timedOut, cancel } = usePaymentStatus({
    reference,
    onTerminal: (res) => {
      if (res.status === 'completed') {
        onSuccess(res);
      } else if (res.status === 'failed' || res.status === 'cancelled' || res.status === 'expired') {
        onFailure(res, res.status);
      }
    },
  });

  React.useEffect(() => {
    if (timedOut) {
      onFailure(data, 'timeout');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [timedOut]);

  const isTerminal = isTerminalStatus(status);
  const showSpinner = !isTerminal && !timedOut;

  function handleCancel() {
    cancel();
    onCancel?.();
  }

  return (
    <SafeAreaView edges={['top']} className="flex-1 bg-bg">
      <ScreenHeader title={title} />

      <View className="flex-1 px-6 items-center justify-center">
        {/* Phone icon with pulsing ring */}
        <View className="h-28 w-28 rounded-full bg-bgElevated border border-border items-center justify-center">
          {showSpinner ? (
            <Ionicons name="phone-portrait-outline" size={44} color={colors.accent} />
          ) : status === 'completed' ? (
            <Ionicons name="checkmark-circle" size={56} color={colors.success} />
          ) : (
            <Ionicons name="close-circle" size={56} color={colors.error} />
          )}
        </View>

        <Text className="mt-8 text-textPrimary text-[20px] font-semibold text-center">
          {showSpinner ? 'Check your phone' : statusLabel(status)}
        </Text>
        <Text className="mt-2 text-textSecondary text-[14.5px] leading-relaxed text-center max-w-[300px]">
          {showSpinner
            ? 'Approve the prompt on your mobile money app to complete this payment.'
            : status === 'completed'
              ? `${data?.amount.toLocaleString() ?? ''} ${data?.currency ?? ''} received successfully.`
              : 'You can retry the payment from the previous screen.'}
        </Text>

        {showSpinner ? (
          <View className="mt-8 flex-row items-center gap-3">
            <ActivityIndicator color={colors.accent} />
            <Text className="font-mono text-[12px] text-textTertiary">
              {isPolling ? 'Waiting for confirmation…' : 'Checking…'}
            </Text>
          </View>
        ) : null}

        {/* Reference footer */}
        <View className="mt-10 self-stretch border-t border-border pt-4">
          <Text className="text-textTertiary text-[11px] uppercase tracking-widest text-center">
            Reference
          </Text>
          <Text className="mt-1 font-mono text-[12px] text-textSecondary text-center" selectable>
            {reference}
          </Text>
        </View>
      </View>

      {/* Cancel button — only while polling */}
      {showSpinner ? (
        <View className="px-4 pb-6">
          <Button
            title="Cancel"
            onPress={handleCancel}
            variant="secondary"
            size="md"
          />
        </View>
      ) : null}
    </SafeAreaView>
  );
}

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';
import type { Currency } from '../lib/dgateway';

export interface SubscriptionPlan {
  id: number;
  name: string;
  amount: number;
  currency: Currency;
  interval: 'day' | 'week' | 'month' | 'year';
  intervalCount?: number;
  trialDays?: number;
  features: string[];
  /** Highlight this plan (e.g., "Most popular"). */
  highlight?: boolean;
}

interface SubscriptionPlanCardProps {
  plan: SubscriptionPlan;
  selected?: boolean;
  onSelect: (plan: SubscriptionPlan) => void;
  className?: string;
}

function intervalLabel(p: SubscriptionPlan): string {
  const count = p.intervalCount ?? 1;
  const unit = p.interval + (count > 1 ? 's' : '');
  return count === 1 ? `per ${p.interval}` : `every ${count} ${unit}`;
}

export function SubscriptionPlanCard({
  plan,
  selected = false,
  onSelect,
  className,
}: SubscriptionPlanCardProps) {
  return (
    <Pressable
      onPress={() => onSelect(plan)}
      accessibilityRole="button"
      accessibilityState={{ selected }}
      accessibilityLabel={`${plan.name} — ${plan.amount} ${plan.currency} ${intervalLabel(plan)}`}
      className={cn(
        'rounded-2xl p-5 border bg-bgElevated',
        selected ? 'border-accent' : 'border-border',
        plan.highlight && !selected && 'border-borderStrong',
        className,
      )}
    >
      {plan.highlight ? (
        <View className="self-start mb-3 px-2 py-0.5 rounded-full bg-accent/15">
          <Text className="text-accent text-[10px] uppercase tracking-widest font-semibold">
            Most popular
          </Text>
        </View>
      ) : null}

      <View className="flex-row items-center justify-between">
        <Text className="text-textPrimary text-[18px] font-semibold">{plan.name}</Text>
        {selected ? (
          <Ionicons name="checkmark-circle" size={22} color={colors.accent} />
        ) : (
          <View className="h-5 w-5 rounded-full border border-border" />
        )}
      </View>

      <View className="mt-3 flex-row items-baseline gap-1.5">
        <Text className="text-textPrimary text-[28px] font-bold">
          {plan.amount.toLocaleString()}
        </Text>
        <Text className="text-textSecondary text-[14px] font-medium">{plan.currency}</Text>
        <Text className="text-textTertiary text-[12.5px] ml-1">{intervalLabel(plan)}</Text>
      </View>

      {plan.trialDays ? (
        <Text className="mt-1 text-success text-[12px] font-medium">
          {plan.trialDays}-day free trial
        </Text>
      ) : null}

      {plan.features.length > 0 ? (
        <View className="mt-4 gap-2">
          {plan.features.map((f) => (
            <View key={f} className="flex-row items-start gap-2">
              <Ionicons name="checkmark" size={16} color={colors.accent} style={{ marginTop: 2 }} />
              <Text className="flex-1 text-textSecondary text-[13.5px] leading-snug">{f}</Text>
            </View>
          ))}
        </View>
      ) : null}
    </Pressable>
  );
}

import React from 'react';
import { View, Text, ScrollView, Alert } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScreenHeader } from '../shared/screen-header';
import { colors } from '../lib/theme';
import { dgateway, type Currency, type SubscriptionState } from '../lib/dgateway';

export interface ActiveSubscription {
  id: number | string;
  planName: string;
  amount: number;
  currency: Currency;
  interval: 'day' | 'week' | 'month' | 'year';
  intervalCount?: number;
  state: SubscriptionState;
  nextChargeAt?: string;
  trialEndsAt?: string;
  cancelledAt?: string;
  paymentMethodLast4?: string;
  paymentMethodLabel?: string;
}

interface SubscriptionManageScreenProps {
  subscription: ActiveSubscription;
  onCancelled?: (subscriptionId: ActiveSubscription['id']) => void;
  onPayNow?: () => void;
  title?: string;
}

const STATE_TO_VARIANT: Record<SubscriptionState, 'success' | 'warning' | 'error' | 'info' | 'neutral'> = {
  trialing: 'info',
  active: 'success',
  past_due: 'warning',
  cancelled: 'neutral',
  expired: 'error',
};

const STATE_LABEL: Record<SubscriptionState, string> = {
  trialing: 'Trialing',
  active: 'Active',
  past_due: 'Payment due',
  cancelled: 'Cancelled',
  expired: 'Expired',
};

function formatDate(iso?: string): string {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

export function SubscriptionManageScreen({
  subscription,
  onCancelled,
  onPayNow,
  title = 'Your subscription',
}: SubscriptionManageScreenProps) {
  const [cancelling, setCancelling] = React.useState(false);

  function confirmCancel() {
    Alert.alert(
      'Cancel subscription?',
      `You'll keep access until ${formatDate(subscription.nextChargeAt)}. After that, the subscription ends.`,
      [
        { text: 'Keep subscription', style: 'cancel' },
        {
          text: 'Cancel subscription',
          style: 'destructive',
          onPress: handleCancel,
        },
      ],
    );
  }

  async function handleCancel() {
    setCancelling(true);
    try {
      await dgateway.cancelSubscription(subscription.id);
      onCancelled?.(subscription.id);
    } catch (err) {
      Alert.alert('Could not cancel', (err as Error).message || 'Please try again.');
    } finally {
      setCancelling(false);
    }
  }

  const intervalUnit = subscription.intervalCount && subscription.intervalCount > 1
    ? `${subscription.intervalCount} ${subscription.interval}s`
    : subscription.interval;

  return (
    <SafeAreaView edges={['top']} className="flex-1 bg-bg">
      <ScreenHeader title={title} />

      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 32 }}>
        {/* Plan card */}
        <View className="rounded-2xl bg-bgElevated border border-border p-5">
          <View className="flex-row items-center justify-between">
            <Text className="text-textPrimary text-[18px] font-semibold">
              {subscription.planName}
            </Text>
            <Badge
              label={STATE_LABEL[subscription.state]}
              variant={STATE_TO_VARIANT[subscription.state]}
            />
          </View>

          <View className="mt-3 flex-row items-baseline gap-1.5">
            <Text className="text-textPrimary text-[28px] font-bold">
              {subscription.amount.toLocaleString()}
            </Text>
            <Text className="text-textSecondary text-[14px] font-medium">
              {subscription.currency}
            </Text>
            <Text className="text-textTertiary text-[13px] ml-1">
              every {intervalUnit}
            </Text>
          </View>
        </View>

        {/* Past-due banner */}
        {subscription.state === 'past_due' ? (
          <View className="mt-4 rounded-xl border border-warning bg-warningLight p-4">
            <View className="flex-row items-start gap-3">
              <Ionicons name="warning" size={20} color={colors.warning} style={{ marginTop: 1 }} />
              <View className="flex-1">
                <Text className="text-warning text-[14px] font-semibold">
                  Your last payment didn&apos;t go through
                </Text>
                <Text className="text-textSecondary text-[13px] mt-1 leading-snug">
                  Pay now to keep your subscription active. We&apos;ll retry automatically before
                  cancelling.
                </Text>
                <View className="mt-3 self-start">
                  <Button title="Pay now" onPress={() => onPayNow?.()} size="sm" />
                </View>
              </View>
            </View>
          </View>
        ) : null}

        {/* Details rows */}
        <View className="mt-4 rounded-2xl bg-bgElevated border border-border">
          <DetailRow
            icon="calendar-outline"
            label="Next charge"
            value={formatDate(subscription.nextChargeAt)}
          />
          <Divider />
          {subscription.trialEndsAt ? (
            <>
              <DetailRow
                icon="hourglass-outline"
                label="Trial ends"
                value={formatDate(subscription.trialEndsAt)}
              />
              <Divider />
            </>
          ) : null}
          {subscription.paymentMethodLabel ? (
            <>
              <DetailRow
                icon="card-outline"
                label="Payment method"
                value={
                  subscription.paymentMethodLast4
                    ? `${subscription.paymentMethodLabel} ···· ${subscription.paymentMethodLast4}`
                    : subscription.paymentMethodLabel
                }
              />
              <Divider />
            </>
          ) : null}
          <DetailRow
            icon="receipt-outline"
            label="Subscription ID"
            value={String(subscription.id)}
            mono
          />
        </View>

        {/* Cancel action */}
        {subscription.state !== 'cancelled' && subscription.state !== 'expired' ? (
          <View className="mt-6">
            <Button
              title={cancelling ? 'Cancelling…' : 'Cancel subscription'}
              variant="destructive"
              onPress={confirmCancel}
              loading={cancelling}
              size="md"
            />
          </View>
        ) : (
          <View className="mt-6 rounded-xl bg-bgElevated border border-border p-4">
            <Text className="text-textSecondary text-[13.5px] leading-relaxed text-center">
              This subscription ended on {formatDate(subscription.cancelledAt)}. Subscribe again to
              restore access.
            </Text>
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
}

function DetailRow({
  icon,
  label,
  value,
  mono,
}: {
  icon: React.ComponentProps<typeof Ionicons>['name'];
  label: string;
  value: string;
  mono?: boolean;
}) {
  return (
    <View className="flex-row items-center justify-between px-4 py-3.5">
      <View className="flex-row items-center gap-3">
        <Ionicons name={icon} size={18} color={colors.textTertiary} />
        <Text className="text-textSecondary text-[13.5px]">{label}</Text>
      </View>
      <Text
        className={['text-textPrimary text-[13.5px]', mono ? 'font-mono text-[12px]' : ''].join(' ')}
        numberOfLines={1}
      >
        {value}
      </Text>
    </View>
  );
}

function Divider() {
  return <View className="h-px bg-border mx-4" />;
}

import React from 'react';
import { Alert } from 'react-native';
import { useStripe } from '@stripe/stripe-react-native';
import { Button } from '../ui/button';

/**
 * Stripe one-time payment button (Payment Sheet flow).
 *
 * Server requirements: your backend must expose
 *   POST /api/stripe/create-payment-intent
 *   → returns { clientSecret, ephemeralKey, customer, publishableKey? }
 *
 * Wrap your app root with <StripeProvider publishableKey="pk_test_…"> from
 * @stripe/stripe-react-native before rendering this button.
 *
 * https://docs.stripe.com/payments/accept-a-payment?platform=react-native
 */

interface StripePayButtonProps {
  amount: number;
  currency: string;
  /** Description shown on the buyer's statement. */
  description: string;
  /** Pre-filled buyer email — speeds up Payment Sheet. */
  buyerEmail?: string;
  /** Merchant display name. */
  merchantDisplayName: string;
  /** Callback hit when Stripe confirms the payment succeeded. */
  onSuccess: (paymentIntentId: string) => void;
  /** Callback hit when the buyer cancels or payment fails. */
  onError?: (error: { code: string; message: string }) => void;
  /** Backend endpoint to mint the PaymentIntent. Default: /api/stripe/create-payment-intent */
  endpoint?: string;
  label?: string;
  disabled?: boolean;
}

export function StripePayButton({
  amount,
  currency,
  description,
  buyerEmail,
  merchantDisplayName,
  onSuccess,
  onError,
  endpoint = '/api/stripe/create-payment-intent',
  label = 'Pay with card',
  disabled = false,
}: StripePayButtonProps) {
  const { initPaymentSheet, presentPaymentSheet } = useStripe();
  const [loading, setLoading] = React.useState(false);

  async function handlePay() {
    setLoading(true);
    try {
      // 1. Mint a PaymentIntent on your backend
      const apiUrl = process.env.EXPO_PUBLIC_API_URL ?? 'http://localhost:3000';
      const res = await fetch(`${apiUrl.replace(/\/$/, '')}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount, currency, description, buyerEmail }),
      });
      if (!res.ok) throw new Error(`Backend returned ${res.status}`);
      const { clientSecret, ephemeralKey, customer } = await res.json();
      if (!clientSecret) throw new Error('Missing clientSecret from backend');

      // 2. Initialise the Payment Sheet
      const init = await initPaymentSheet({
        merchantDisplayName,
        customerId: customer,
        customerEphemeralKeySecret: ephemeralKey,
        paymentIntentClientSecret: clientSecret,
        defaultBillingDetails: buyerEmail ? { email: buyerEmail } : undefined,
        allowsDelayedPaymentMethods: true,
        returnURL: 'vibekit-native://stripe-redirect',
      });
      if (init.error) throw new Error(init.error.message);

      // 3. Present the sheet
      const result = await presentPaymentSheet();
      if (result.error) {
        if (result.error.code === 'Canceled') {
          onError?.({ code: 'cancelled', message: 'Payment cancelled' });
        } else {
          onError?.({ code: result.error.code, message: result.error.message });
          Alert.alert('Payment failed', result.error.message);
        }
        return;
      }

      // 4. Success — extract intent id (last segment of client_secret before _secret_)
      const intentId = clientSecret.split('_secret_')[0];
      onSuccess(intentId);
    } catch (err) {
      const message = (err as Error).message || 'Could not start payment';
      onError?.({ code: 'init_failed', message });
      Alert.alert('Payment unavailable', message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <Button
      title={label}
      onPress={handlePay}
      loading={loading}
      disabled={disabled}
      icon="card-outline"
      variant="primary"
      size="lg"
    />
  );
}

import React from 'react';
import { Alert } from 'react-native';
import { useStripe } from '@stripe/stripe-react-native';
import { Button } from '../ui/button';

/**
 * Stripe subscription button (Payment Sheet with SetupIntent / Subscription).
 *
 * Server requirements: your backend must expose
 *   POST /api/stripe/create-subscription
 *   → returns { clientSecret, ephemeralKey, customer, subscriptionId, type: 'setup' | 'payment' }
 *
 * "type" tells the sheet which secret you returned:
 *   - 'payment' — PaymentIntent (first invoice charged immediately)
 *   - 'setup'   — SetupIntent (trial; card saved without charge)
 *
 * Wrap your app root with <StripeProvider publishableKey="pk_test_…">.
 * https://docs.stripe.com/billing/subscriptions/build-subscriptions?platform=react-native
 */

interface StripeSubscriptionButtonProps {
  /** Stripe price id (e.g., price_1AbcD…). */
  priceId: string;
  /** Buyer email — required for Stripe Customer creation. */
  buyerEmail: string;
  /** Merchant display name. */
  merchantDisplayName: string;
  onSubscribed: (subscriptionId: string) => void;
  onError?: (error: { code: string; message: string }) => void;
  /** Backend endpoint to create the subscription. Default: /api/stripe/create-subscription */
  endpoint?: string;
  label?: string;
  disabled?: boolean;
}

export function StripeSubscriptionButton({
  priceId,
  buyerEmail,
  merchantDisplayName,
  onSubscribed,
  onError,
  endpoint = '/api/stripe/create-subscription',
  label = 'Subscribe',
  disabled = false,
}: StripeSubscriptionButtonProps) {
  const { initPaymentSheet, presentPaymentSheet } = useStripe();
  const [loading, setLoading] = React.useState(false);

  async function handleSubscribe() {
    setLoading(true);
    try {
      const apiUrl = process.env.EXPO_PUBLIC_API_URL ?? 'http://localhost:3000';
      const res = await fetch(`${apiUrl.replace(/\/$/, '')}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priceId, buyerEmail }),
      });
      if (!res.ok) throw new Error(`Backend returned ${res.status}`);

      const {
        clientSecret,
        ephemeralKey,
        customer,
        subscriptionId,
        type,
      } = await res.json();
      if (!clientSecret || !subscriptionId) {
        throw new Error('Missing clientSecret or subscriptionId from backend');
      }

      const isSetup = type === 'setup';
      const init = await initPaymentSheet({
        merchantDisplayName,
        customerId: customer,
        customerEphemeralKeySecret: ephemeralKey,
        paymentIntentClientSecret: !isSetup ? clientSecret : undefined,
        setupIntentClientSecret: isSetup ? clientSecret : undefined,
        defaultBillingDetails: { email: buyerEmail },
        allowsDelayedPaymentMethods: false,
        returnURL: 'vibekit-native://stripe-redirect',
      });
      if (init.error) throw new Error(init.error.message);

      const result = await presentPaymentSheet();
      if (result.error) {
        if (result.error.code === 'Canceled') {
          onError?.({ code: 'cancelled', message: 'Subscription cancelled' });
        } else {
          onError?.({ code: result.error.code, message: result.error.message });
          Alert.alert('Subscription failed', result.error.message);
        }
        return;
      }

      onSubscribed(subscriptionId);
    } catch (err) {
      const message = (err as Error).message || 'Could not start subscription';
      onError?.({ code: 'init_failed', message });
      Alert.alert('Subscription unavailable', message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <Button
      title={label}
      onPress={handleSubscribe}
      loading={loading}
      disabled={disabled}
      icon="repeat-outline"
      variant="primary"
      size="lg"
    />
  );
}

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

export interface BottomTab {
  key: string;
  label: string;
  icon: keyof typeof Ionicons.glyphMap;
  iconActive?: keyof typeof Ionicons.glyphMap;
  /** Numeric badge (or boolean to show a dot). */
  badge?: number | boolean;
}

interface BottomTabsProps {
  tabs: BottomTab[];
  activeKey: string;
  onChange: (key: string) => void;
  /** Override default safe-area bottom inset behaviour. */
  edges?: Array<'top' | 'right' | 'bottom' | 'left'>;
  className?: string;
}

/**
 * Custom tab bar — pair with expo-router's <Tabs> by passing `tabBar={() => <BottomTabs ... />}`,
 * or use standalone above your screen.
 */
export function BottomTabs({
  tabs,
  activeKey,
  onChange,
  edges = ['bottom'],
  className,
}: BottomTabsProps) {
  return (
    <SafeAreaView edges={edges} className={cn('bg-bg', className)}>
      <View className="flex-row items-stretch border-t border-border bg-bg">
        {tabs.map((tab) => {
          const active = tab.key === activeKey;
          return (
            <Pressable
              key={tab.key}
              onPress={() => onChange(tab.key)}
              accessibilityRole="tab"
              accessibilityState={{ selected: active }}
              accessibilityLabel={tab.label}
              className="flex-1 items-center justify-center py-2.5"
              android_ripple={{ color: colors.bgHover, borderless: false }}
            >
              <View>
                <Ionicons
                  name={active ? (tab.iconActive ?? tab.icon) : tab.icon}
                  size={22}
                  color={active ? colors.accent : colors.textTertiary}
                />
                {tab.badge ? (
                  <View
                    className="absolute -top-1 -right-2 min-w-[16px] h-[16px] px-1 rounded-full bg-error items-center justify-center"
                    style={{ minWidth: typeof tab.badge === 'number' ? 16 : 8 }}
                  >
                    {typeof tab.badge === 'number' ? (
                      <Text className="text-white text-[10px] font-bold">
                        {tab.badge > 99 ? '99+' : tab.badge}
                      </Text>
                    ) : null}
                  </View>
                ) : null}
              </View>
              <Text
                className={cn(
                  'text-[11px] mt-1',
                  active ? 'text-accent font-semibold' : 'text-textTertiary',
                )}
              >
                {tab.label}
              </Text>
            </Pressable>
          );
        })}
      </View>
    </SafeAreaView>
  );
}

import React from 'react';
import { View, Text, Pressable, Modal, Animated, Dimensions, type GestureResponderEvent } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

export interface DrawerItem {
  key: string;
  label: string;
  icon?: keyof typeof Ionicons.glyphMap;
  badge?: number;
  onPress?: () => void;
  /** Renders as a divider when true. */
  divider?: boolean;
  /** Visual variant — destructive items render in error color. */
  variant?: 'default' | 'destructive';
}

export interface DrawerHeader {
  title: string;
  subtitle?: string;
  avatarUrl?: string;
}

interface AppDrawerProps {
  visible: boolean;
  onClose: () => void;
  items: DrawerItem[];
  activeKey?: string;
  header?: DrawerHeader;
  footer?: React.ReactNode;
  /** Drawer width in px (default 304 — Material). Use a number, not a string. */
  width?: number;
}

const SCREEN = Dimensions.get('window');

export function AppDrawer({
  visible,
  onClose,
  items,
  activeKey,
  header,
  footer,
  width = 304,
}: AppDrawerProps) {
  const translateX = React.useRef(new Animated.Value(-width)).current;
  const backdropOpacity = React.useRef(new Animated.Value(0)).current;

  React.useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(translateX, {
          toValue: 0,
          duration: 240,
          useNativeDriver: true,
        }),
        Animated.timing(backdropOpacity, {
          toValue: 1,
          duration: 240,
          useNativeDriver: true,
        }),
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(translateX, {
          toValue: -width,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.timing(backdropOpacity, {
          toValue: 0,
          duration: 200,
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [visible, width, translateX, backdropOpacity]);

  function handleItemPress(item: DrawerItem) {
    return (_e: GestureResponderEvent) => {
      item.onPress?.();
      onClose();
    };
  }

  return (
    <Modal visible={visible} transparent animationType="none" onRequestClose={onClose}>
      <View style={{ flex: 1, flexDirection: 'row' }}>
        {/* Animated drawer */}
        <Animated.View
          style={{
            width,
            height: SCREEN.height,
            transform: [{ translateX }],
            backgroundColor: colors.bgElevated,
          }}
          className="border-r border-border"
        >
          <SafeAreaView edges={['top', 'bottom', 'left']} className="flex-1">
            {/* Header */}
            {header ? (
              <View className="px-5 py-5 border-b border-border">
                <View className="flex-row items-center gap-3">
                  {header.avatarUrl ? (
                    <View
                      className="h-12 w-12 rounded-full bg-bgSubtle border border-border"
                    />
                  ) : (
                    <View className="h-12 w-12 rounded-full bg-accent/15 items-center justify-center">
                      <Text className="text-accent font-semibold text-[18px]">
                        {header.title.charAt(0).toUpperCase()}
                      </Text>
                    </View>
                  )}
                  <View className="flex-1">
                    <Text className="text-textPrimary text-[15px] font-semibold" numberOfLines={1}>
                      {header.title}
                    </Text>
                    {header.subtitle ? (
                      <Text className="text-textTertiary text-[12.5px]" numberOfLines={1}>
                        {header.subtitle}
                      </Text>
                    ) : null}
                  </View>
                </View>
              </View>
            ) : null}

            {/* Items */}
            <View className="flex-1 py-2">
              {items.map((item) => {
                if (item.divider) {
                  return <View key={item.key} className="h-px bg-border my-2 mx-4" />;
                }
                const active = item.key === activeKey;
                const isDestructive = item.variant === 'destructive';
                return (
                  <Pressable
                    key={item.key}
                    onPress={handleItemPress(item)}
                    accessibilityRole="menuitem"
                    accessibilityState={{ selected: active }}
                    className={cn(
                      'flex-row items-center gap-3 px-5 py-3 mx-2 rounded-lg',
                      active && 'bg-accent/10',
                    )}
                    android_ripple={{ color: colors.bgHover }}
                  >
                    {item.icon ? (
                      <Ionicons
                        name={item.icon}
                        size={20}
                        color={isDestructive ? colors.error : active ? colors.accent : colors.textSecondary}
                      />
                    ) : null}
                    <Text
                      className={cn(
                        'flex-1 text-[14.5px]',
                        isDestructive ? 'text-error' : active ? 'text-accent font-semibold' : 'text-textPrimary',
                      )}
                    >
                      {item.label}
                    </Text>
                    {typeof item.badge === 'number' && item.badge > 0 ? (
                      <View className="px-2 py-0.5 rounded-full bg-accent/15">
                        <Text className="text-accent text-[11px] font-semibold">
                          {item.badge > 99 ? '99+' : item.badge}
                        </Text>
                      </View>
                    ) : null}
                  </Pressable>
                );
              })}
            </View>

            {/* Footer */}
            {footer ? <View className="border-t border-border p-4">{footer}</View> : null}
          </SafeAreaView>
        </Animated.View>

        {/* Backdrop */}
        <Animated.View style={{ flex: 1, opacity: backdropOpacity }}>
          <Pressable onPress={onClose} accessibilityLabel="Close menu" className="flex-1 bg-black/60" />
        </Animated.View>
      </View>
    </Modal>
  );
}

import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

interface StatCardProps {
  label: string;
  value: string | number;
  /** Sub-value shown next to the main value (e.g. currency). */
  unit?: string;
  /** Optional delta vs prior period — positive = up. */
  delta?: number;
  deltaLabel?: string;
  /** Optional sparkline data points (0..1 normalised). */
  sparkline?: number[];
  icon?: keyof typeof Ionicons.glyphMap;
  onPress?: () => void;
  /** Visual emphasis variant. */
  variant?: 'default' | 'accent';
  className?: string;
}

export function StatCard({
  label,
  value,
  unit,
  delta,
  deltaLabel = 'vs last period',
  sparkline,
  icon,
  onPress,
  variant = 'default',
  className,
}: StatCardProps) {
  const isUp = typeof delta === 'number' && delta > 0;
  const isDown = typeof delta === 'number' && delta < 0;
  const deltaColor = isUp ? colors.success : isDown ? colors.error : colors.textTertiary;

  const Container = onPress ? Pressable : View;

  return (
    <Container
      onPress={onPress}
      accessibilityRole={onPress ? 'button' : undefined}
      accessibilityLabel={`${label}: ${value}${unit ? ' ' + unit : ''}`}
      className={cn(
        'rounded-2xl p-4 border bg-bgElevated',
        variant === 'accent' ? 'border-accent/40' : 'border-border',
        className,
      )}
    >
      <View className="flex-row items-center justify-between">
        <Text className="text-textTertiary text-[11.5px] uppercase tracking-widest font-medium">
          {label}
        </Text>
        {icon ? (
          <View className="h-8 w-8 rounded-lg items-center justify-center bg-bgSubtle">
            <Ionicons name={icon} size={16} color={variant === 'accent' ? colors.accent : colors.textSecondary} />
          </View>
        ) : null}
      </View>

      <View className="mt-2 flex-row items-baseline gap-1.5">
        <Text className="text-textPrimary text-[26px] font-bold tabular-nums">
          {typeof value === 'number' ? value.toLocaleString() : value}
        </Text>
        {unit ? (
          <Text className="text-textSecondary text-[13px] font-medium">{unit}</Text>
        ) : null}
      </View>

      {typeof delta === 'number' || sparkline?.length ? (
        <View className="mt-2 flex-row items-center justify-between">
          {typeof delta === 'number' ? (
            <View className="flex-row items-center gap-1">
              <Ionicons
                name={isUp ? 'trending-up' : isDown ? 'trending-down' : 'remove'}
                size={14}
                color={deltaColor}
              />
              <Text className="text-[12px] font-semibold" style={{ color: deltaColor }}>
                {delta > 0 ? '+' : ''}{delta.toFixed(1)}%
              </Text>
              <Text className="text-textTertiary text-[11px] ml-1">{deltaLabel}</Text>
            </View>
          ) : (
            <View />
          )}
          {sparkline && sparkline.length > 1 ? (
            <Sparkline data={sparkline} color={isDown ? colors.error : colors.accent} />
          ) : null}
        </View>
      ) : null}
    </Container>
  );
}

/** Tiny SVG-free sparkline using View bars. ~32px wide. */
function Sparkline({ data, color }: { data: number[]; color: string }) {
  const max = Math.max(...data, 1);
  return (
    <View className="flex-row items-end gap-[2px] h-5">
      {data.map((v, i) => (
        <View
          key={i}
          style={{
            width: 3,
            height: Math.max(2, (v / max) * 20),
            backgroundColor: color,
            opacity: 0.4 + (i / data.length) * 0.6,
            borderRadius: 1.5,
          }}
        />
      ))}
    </View>
  );
}

