import React from 'react';
import { View, Text } from 'react-native';
import { PieChart } from 'react-native-gifted-charts';
import { cn } from '../lib/utils';
import { colors } from '../lib/theme';

export interface PieSlice {
  value: number;
  label: string;
  /** Optional color override — defaults to a rotating accent palette. */
  color?: string;
}

interface ChartPieProps {
  data: PieSlice[];
  title?: string;
  subtitle?: string;
  /** Donut variant (centered total or label). */
  donut?: boolean;
  /** Donut center label override — falls back to the sum. */
  centerLabel?: string;
  /** Donut center sub-label. */
  centerSubLabel?: string;
  /** Show right-side legend. */
  showLegend?: boolean;
  size?: number;
  className?: string;
}

const PALETTE = [
  colors.accent,
  '#34D399',  // emerald
  '#F59E0B',  // amber
  '#F87171',  // rose
  '#60A5FA',  // sky
  '#A78BFA',  // violet
  '#FBBF24',  // yellow
  '#22D3EE',  // cyan
];

export function ChartPie({
  data,
  title,
  subtitle,
  donut = true,
  centerLabel,
  centerSubLabel,
  showLegend = true,
  size = 180,
  className,
}: ChartPieProps) {
  const total = data.reduce((sum, s) => sum + s.value, 0);

  const decorated = data.map((s, i) => ({
    ...s,
    color: s.color ?? PALETTE[i % PALETTE.length],
  }));

  return (
    <View className={cn('rounded-2xl border border-border bg-bgElevated p-4', className)}>
      {(title || subtitle) ? (
        <View className="mb-3">
          {title ? (
            <Text className="text-textPrimary text-[15px] font-semibold">{title}</Text>
          ) : null}
          {subtitle ? (
            <Text className="text-textTertiary text-[12.5px] mt-0.5">{subtitle}</Text>
          ) : null}
        </View>
      ) : null}

      <View className="flex-row items-center gap-5">
        <PieChart
          data={decorated}
          donut={donut}
          innerRadius={donut ? size * 0.32 : 0}
          radius={size / 2}
          innerCircleColor={colors.bgElevated}
          centerLabelComponent={
            donut
              ? () => (
                  <View className="items-center">
                    <Text className="text-textPrimary text-[20px] font-bold">
                      {centerLabel ?? total.toLocaleString()}
                    </Text>
                    {centerSubLabel ? (
                      <Text className="text-textTertiary text-[11px]">{centerSubLabel}</Text>
                    ) : null}
                  </View>
                )
              : undefined
          }
        />

        {showLegend ? (
          <View className="flex-1 gap-2">
            {decorated.map((slice) => {
              const pct = total > 0 ? Math.round((slice.value / total) * 100) : 0;
              return (
                <View key={slice.label} className="flex-row items-center gap-2.5">
                  <View
                    style={{ backgroundColor: slice.color, width: 10, height: 10, borderRadius: 3 }}
                  />
                  <Text className="flex-1 text-textSecondary text-[12.5px]" numberOfLines={1}>
                    {slice.label}
                  </Text>
                  <Text className="text-textPrimary text-[12.5px] font-semibold tabular-nums">
                    {pct}%
                  </Text>
                </View>
              );
            })}
          </View>
        ) : null}
      </View>
    </View>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatCurrencyInput(text: string): string {
  const digits = text.replace(/\D/g, '');
  if (!digits) return '';
  const num = parseInt(digits, 10);
  return num.toLocaleString('en-US');
}

export function formatPrice(amount: number, currency = 'USD'): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol',
  }).format(amount);
}

export function formatPriceCompact(amount: number): string {
  if (amount >= 1_000_000) return (amount / 1_000_000).toFixed(1) + 'M';
  if (amount >= 1_000) return (amount / 1_000).toFixed(1) + 'K';
  return amount.toString();
}

import React from 'react';
import { QueryClient, QueryClientProvider, focusManager, onlineManager } from '@tanstack/react-query';
import { AppState, type AppStateStatus, Platform } from 'react-native';
import * as Network from 'expo-network';

/**
 * VibeKit Native API client + provider.
 *
 * Wraps your app in a TanStack Query provider with sensible mobile defaults:
 *   - retries network errors with exponential backoff
 *   - refetches when the app comes back to the foreground
 *   - tracks online/offline state via expo-network
 *
 * Wire into your root `_layout.tsx`:
 *
 *   import { ApiProvider } from '@/components/lib/api-client';
 *
 *   export default function RootLayout() {
 *     return (
 *       <ApiProvider>
 *         <Slot />
 *       </ApiProvider>
 *     );
 *   }
 */

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 2,
      retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 30_000),
      staleTime: 60_000,
      gcTime: 5 * 60_000,
      refetchOnWindowFocus: true,
    },
    mutations: {
      retry: 1,
    },
  },
});

function onAppStateChange(status: AppStateStatus) {
  if (Platform.OS !== 'web') {
    focusManager.setFocused(status === 'active');
  }
}

interface ApiProviderProps {
  children: React.ReactNode;
}

export function ApiProvider({ children }: ApiProviderProps) {
  React.useEffect(() => {
    const sub = AppState.addEventListener('change', onAppStateChange);
    return () => sub.remove();
  }, []);

  React.useEffect(() => {
    return onlineManager.subscribe(() => {
      // no-op — we set onlineManager via the effect below
    });
  }, []);

  React.useEffect(() => {
    let mounted = true;

    const setOnlineFromNetwork = async () => {
      try {
        const state = await Network.getNetworkStateAsync();
        if (mounted) {
          onlineManager.setOnline(Boolean(state.isConnected && state.isInternetReachable !== false));
        }
      } catch {
        // expo-network not available — assume online
        onlineManager.setOnline(true);
      }
    };

    setOnlineFromNetwork();
    const interval = setInterval(setOnlineFromNetwork, 30_000);

    return () => {
      mounted = false;
      clearInterval(interval);
    };
  }, []);

  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>;
}

export { queryClient };

import Constants from 'expo-constants';

/**
 * VibeKit Native — DGateway client.
 *
 * IMPORTANT: This module talks to YOUR backend, not directly to DGateway.
 * Never bundle the DGateway API key into the mobile app. Your backend
 * proxies these calls and adds the X-API-Key header server-side.
 *
 * Configure your backend URL via app.json `extra.apiUrl` or EXPO_PUBLIC_API_URL.
 * Your backend must expose:
 *   POST /api/checkout/start             → DGateway /v1/payments/collect
 *   GET  /api/checkout/status/:reference → DGateway /v1/transactions/:ref/status
 *   POST /api/subscriptions/start        → DGateway /v1/subscriptions
 *   POST /api/subscriptions/:id/cancel   → DGateway cancel
 *
 * Live DGateway docs: https://dgateway.com/docs
 */

const API_URL =
  Constants.expoConfig?.extra?.apiUrl ??
  process.env.EXPO_PUBLIC_API_URL ??
  'http://localhost:3000';

export type Currency = 'UGX' | 'KES' | 'TZS' | 'RWF' | 'USD';

export type PaymentStatus =
  | 'pending'
  | 'processing'
  | 'completed'
  | 'failed'
  | 'cancelled'
  | 'expired';

export interface CollectRequest {
  amount: number;            // whole units of currency (no decimals for mobile money)
  currency: Currency;
  phoneNumber: string;       // 07X / 2567X / +2567X — server normalises
  description: string;
  metadata?: Record<string, string | number | boolean>;
}

export interface CollectResponse {
  reference: string;
  status: PaymentStatus;
  provider: 'iotec' | 'relworx' | 'stripe' | string;
}

export interface PaymentStatusResponse {
  reference: string;
  status: PaymentStatus;
  provider: string;
  providerRef?: string;
  amount: number;
  currency: Currency;
  phoneNumber?: string;
  completedAt?: string;
  failureReason?: string;
}

export interface SubscriptionRequest {
  planId: number;
  phoneNumber: string;
  buyerEmail: string;
  metadata?: Record<string, string | number | boolean>;
}

export type SubscriptionState =
  | 'trialing'
  | 'active'
  | 'past_due'
  | 'cancelled'
  | 'expired';

export interface SubscriptionResponse {
  id: number | string;
  reference: string;
  status: PaymentStatus;
  state: SubscriptionState;
  planId: number;
  planName: string;
  amount: number;
  currency: Currency;
  interval: 'day' | 'week' | 'month' | 'year';
  intervalCount: number;
  nextChargeAt?: string;
  trialEndsAt?: string;
  cancelledAt?: string;
}

class DGatewayError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
    this.name = 'DGatewayError';
  }
}

async function request<T>(
  path: string,
  init?: RequestInit & { timeoutMs?: number },
): Promise<T> {
  const url = `${API_URL.replace(/\/$/, '')}${path}`;
  const timeoutMs = init?.timeoutMs ?? 30_000;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const res = await fetch(url, {
      ...init,
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        ...(init?.headers ?? {}),
      },
    });

    const text = await res.text();
    const body = text ? JSON.parse(text) : {};

    if (!res.ok) {
      throw new DGatewayError(
        res.status,
        body?.code ?? 'request_failed',
        body?.message ?? `Request failed with status ${res.status}`,
      );
    }

    return (body?.data ?? body) as T;
  } catch (err) {
    if (err instanceof DGatewayError) throw err;
    if ((err as Error).name === 'AbortError') {
      throw new DGatewayError(408, 'timeout', `Request timed out after ${timeoutMs}ms`);
    }
    throw new DGatewayError(0, 'network_error', (err as Error).message || 'Network error');
  } finally {
    clearTimeout(timer);
  }
}

export const dgateway = {
  startPayment(body: CollectRequest): Promise<CollectResponse> {
    return request<CollectResponse>('/api/checkout/start', {
      method: 'POST',
      body: JSON.stringify(body),
    });
  },

  getStatus(reference: string): Promise<PaymentStatusResponse> {
    return request<PaymentStatusResponse>(
      `/api/checkout/status/${encodeURIComponent(reference)}`,
    );
  },

  startSubscription(body: SubscriptionRequest): Promise<SubscriptionResponse> {
    return request<SubscriptionResponse>('/api/subscriptions/start', {
      method: 'POST',
      body: JSON.stringify(body),
    });
  },

  cancelSubscription(id: number | string): Promise<{ id: number | string; state: SubscriptionState }> {
    return request<{ id: number | string; state: SubscriptionState }>(
      `/api/subscriptions/${encodeURIComponent(String(id))}/cancel`,
      { method: 'POST' },
    );
  },
};

export { DGatewayError };

export function isTerminalStatus(status: PaymentStatus): boolean {
  return status === 'completed' || status === 'failed' || status === 'cancelled' || status === 'expired';
}

export function statusLabel(status: PaymentStatus): string {
  switch (status) {
    case 'pending':
    case 'processing':
      return 'Check your phone and approve the prompt';
    case 'completed':
      return 'Payment successful';
    case 'failed':
      return 'Payment failed';
    case 'cancelled':
      return 'Payment cancelled';
    case 'expired':
      return 'Prompt expired — try again';
    default:
      return 'Processing…';
  }
}

import { MMKV } from 'react-native-mmkv';

/**
 * VibeKit Native — fast key-value storage backed by MMKV.
 *
 * MMKV is ~30× faster than AsyncStorage, runs on the JS thread without
 * crossing the bridge, and supports encryption. Use it for tokens,
 * preferences, cached responses, and anything else AsyncStorage was
 * doing.
 *
 * For sensitive secrets (auth tokens, biometric data), pair MMKV with
 * expo-secure-store via the `encryptionKey` option below or store the
 * sensitive value in SecureStore and a non-sensitive reference here.
 *
 * Docs: https://github.com/mrousavy/react-native-mmkv
 *
 * Usage:
 *   import { storage } from '@/lib/storage';
 *
 *   storage.setString('theme', 'dark');
 *   const theme = storage.getString('theme');           // 'dark'
 *
 *   storage.setObject('user', { id: 1, name: 'Jane' });
 *   const user = storage.getObject<{ id: number; name: string }>('user');
 *
 *   storage.delete('user');
 *   storage.clearAll();
 */

const mmkv = new MMKV({
  id: 'vibekit-native',
  // To encrypt the entire instance, derive a key (e.g., from expo-secure-store)
  // and pass it here. Don't hard-code the key.
  // encryptionKey: someKeyFromSecureStore,
});

export const storage = {
  /* String */
  setString(key: string, value: string): void {
    mmkv.set(key, value);
  },
  getString(key: string): string | undefined {
    return mmkv.getString(key);
  },

  /* Boolean */
  setBoolean(key: string, value: boolean): void {
    mmkv.set(key, value);
  },
  getBoolean(key: string): boolean | undefined {
    return mmkv.getBoolean(key);
  },

  /* Number */
  setNumber(key: string, value: number): void {
    mmkv.set(key, value);
  },
  getNumber(key: string): number | undefined {
    return mmkv.getNumber(key);
  },

  /* JSON */
  setObject<T>(key: string, value: T): void {
    mmkv.set(key, JSON.stringify(value));
  },
  getObject<T>(key: string): T | undefined {
    const raw = mmkv.getString(key);
    if (raw == null) return undefined;
    try {
      return JSON.parse(raw) as T;
    } catch {
      return undefined;
    }
  },

  /* Maintenance */
  delete(key: string): void {
    mmkv.delete(key);
  },
  clearAll(): void {
    mmkv.clearAll();
  },
  contains(key: string): boolean {
    return mmkv.contains(key);
  },
  getAllKeys(): string[] {
    return mmkv.getAllKeys();
  },
};

export { mmkv };
